-- 読み取り専用。結果をDB設計レビューへ添付する。氏名・メールは取得しない。
begin read only;
select jsonb_build_object(
 'captured_at',now(),'version',version(),
 '0040_present',to_regprocedure('public.create_fixed_pair_round(uuid,bigint,integer,integer,text,uuid[],jsonb,uuid)') is not null,
 '0041_present',to_regnamespace('lineup_private') is not null,
 'tables',(select jsonb_agg(jsonb_build_object('name',relname,'rls',relrowsecurity,'acl',relacl) order by relname) from pg_class where oid in('public.events'::regclass,'public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass)),
 'columns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'nullable',is_nullable) order by table_name,ordinal_position) from information_schema.columns where table_schema='public' and table_name in('events','event_participants','rounds','matches','match_players','match_results')),
 'policies',(select jsonb_agg(to_jsonb(p) order by tablename,policyname) from pg_policies p where schemaname='public' and tablename in('events','event_participants','rounds','matches','match_players','match_results')),
 'triggers',(select jsonb_agg(jsonb_build_object('table',tgrelid::regclass,'trigger',pg_get_triggerdef(oid),'function',pg_get_functiondef(tgfoid),'enabled',tgenabled) order by tgrelid,tgname) from pg_trigger where not tgisinternal and tgrelid in('public.events'::regclass,'public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass)),
 'rpc_functions',(select jsonb_agg(jsonb_build_object('function',p.oid::regprocedure,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'definition',pg_get_functiondef(p.oid)) order by p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='fixed_pair_private' or (n.nspname='public' and (p.proname in('create_fixed_pair_round','replace_event_fixed_pairs','finish_fixed_pair_event') or p.prosrc like '%create_fixed_pair_round%'))),
 'constraints',(select jsonb_agg(jsonb_build_object('table',conrelid::regclass,'name',conname,'definition',pg_get_constraintdef(oid)) order by conrelid,conname) from pg_constraint where conrelid in('public.events'::regclass,'public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass)),
 'duplicate_courts',(select coalesce(jsonb_agg(x),'[]') from (select m.round_id,m.court_number,count(*) cards from public.matches m join public.events e on e.id=m.event_id where e.event_mode='auto' group by m.round_id,m.court_number having count(*)>1 or m.court_number not between 1 and 5) x),
 'duplicate_results',(select coalesce(jsonb_agg(x),'[]') from (select r.match_id,count(*) result_count from public.match_results r join public.matches m on m.id=r.match_id join public.events e on e.id=m.event_id where e.event_mode='auto' group by r.match_id having count(*)>1) x),
 'invalid_cards',(select coalesce(jsonb_agg(x),'[]') from (select m.id,m.event_id,m.round_id,count(mp.id) players from public.matches m join public.events e on e.id=m.event_id left join public.match_players mp on mp.match_id=m.id left join public.event_participants p on p.id=mp.participant_id and p.event_id=m.event_id where e.event_mode='auto' group by m.id having count(mp.id)<>4 or count(distinct mp.participant_id)<>4 or count(*) filter(where mp.team='A')<>2 or count(*) filter(where mp.team='B')<>2 or count(p.id)<>4) x),
 'duplicate_round_players',(select coalesce(jsonb_agg(x),'[]') from (select m.round_id,mp.participant_id,count(*) appearances from public.matches m join public.events e on e.id=m.event_id join public.match_players mp on mp.match_id=m.id where e.event_mode='auto' group by m.round_id,mp.participant_id having count(*)>1) x)
) round_lineup_preflight;
rollback;
